function U.fmt(Gb)
Gb=tonumber(Gb)or 0
if Gb>=1e6 then
return string.format(Vee[1970],Gb/1e6)
end
if Gb>=1e4 then
return string.format(Vee[1971],Gb/1e3)
end
return tostring(math.floor(Gb+0.5))
end
function U.clamp(Hb,Ib,Jb)
return math.max(Ib,math.min(Jb,Hb))
end
function U.count(Kb)
local Lb=0
for Mb in pairs(Kb or{})do
Lb=Lb+1
