if Yb~=Vee[1972]or(Xb or 0)>6 then
return nil
end
local Zb={}
for _b,cc in pairs(Wb)do
if type(_b)==Vee[1973]or type(_b)==Vee[880]then
Zb[_b]=U.plain(cc,(Xb or 0)+1)
