Kq[Nq]=Oq
end
local Pq=Jq~=nil and Jq.family==Fq.family and(Jq.buff==nil or Hq.buff==nil or Jq.buff==Hq.buff)
Iq[Fq.pid]={family=Fq.family,name=Fq.name,nums=Kq,buff=Hq.buff or(Jq and Jq.buff),who=Hq.who or Fq.who,trigger=Fq.trigger,keyword=Fq.keyword,sure=(Pq and(tonumber(Jq.runs)or 0)>=1)and Vee[2334]or Vee[2394],runs=(Pq and(tonumber(Jq.runs)or 0)or 0)+1,at=os.time(),why=Hq.why}
P.pasBook[Bq]=Iq
table.insert(Aq,{id=Bq,g=Fq,e=Iq[Fq.pid]})
elseif Gq and type(Hq)==Vee[1972]then
table.insert(Aq,{id=Bq,g=Fq,miss=Hq.why})
else
table.insert(Aq,{id=Bq,g=Fq,miss=Vee[2395]..tostring(Hq)})
end
end
end
end
pb._model={}
return Aq
end
