end
function W.ownSig()
local BN=(type(P.savedTeam)==Vee[1972]and#P.savedTeam>0 and P.savedTeam)or(P.train.on and P.train.on.base)
if type(BN)~=Vee[1972]or#BN==0 then
return nil
