function W.needsHelp(LN)
local MN,NN=pcall(W.sim,LN)
if MN and type(NN)==Vee[1972]and tonumber(NN.p)~=nil then
return tonumber(NN.p)<0.5
end
local ON,PN=pcall(W.rec,LN.key)
