W.MATCHED_DAILY_P=0.7
function W.icWinP(QN)
local RN=QN.rec or W.rec(QN.key)
local SN=W.icLost(QN.room)
local UN=SN and SN.n or 0
local VN=((tonumber(RN.wins)or 0)+(QN.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(RN.runs)or 0)+2)
local WN=W.sim(QN)
local XN,YN=0,0
if WN and tonumber(WN.p)then
local ZN=type(WN.trust)==Vee[1972]and WN.trust or nil
local _N=ZN~=nil and not ZN.ok
local aO=_N and(tonumber(ZN.ratio)or 1)>1
if not _N or(aO and not WN.won)or(_N and not aO and WN.won)then
local bO,cO=pcall(gb.styleP,WN)
XN,YN=(bO and tonumber(cO))or tonumber(WN.p),W.IC.SIM_W
end
end
return(VN*2+XN*YN)/(UN+2+YN)
end
function W.winP(dO)
if dO.kind==Vee[2427]then
return W.icWinP(dO)
end
if dO.kind==Vee[2425]and O.dailyMatch and not O.dailyLoop then
local eO,fO=pcall(W.needsHelp,dO)
if eO and fO then
return W.MATCHED_DAILY_P
end
end
local gO=dO.rec
local hO=dO.p0 or W.PRIOR_WIN[dO.kind]or 0.7
local iO=W.sim(dO)
if iO and not(iO.trust and not iO.trust.ok)then
local jO=iO.calibrated or gO.runs>0
local kO=(iO.trust and iO.trust.ok)and 6 or(jO and 3 or 1.5)
local lO=(jO or iO.hopeless)and 0 or 2
local mO,nO=pcall(gb.styleP,iO)
return(gO.wins+hO*lO+(mO and nO or iO.p)*kO)/(gO.runs+lO+kO)
end
return(gO.wins+hO*2)/(gO.runs+2)
end
function W.minutes(oO)
local pO=oO.rec
local qO=tonumber(pO.timed)or 0
local rO=oO.kind==Vee[1991]and P.simRes[oO.key]
local sO=(qO>0 and pO.sec>0)and(pO.sec/qO/60)or(rO and tonumber(rO.minutes))or W.PRIOR_MIN[oO.kind]or 6
return sO+W.OVERHEAD
end
function W.score(tO)
local uO,vO=((tO.kind==Vee[1989]and tO.rec.runs>0)or tO.kind==Vee[1991]or tO.kind==Vee[2428])and 1 or(tO.kind==Vee[1992]and tO.p0)or W.winP(tO),W.minutes(tO)
local wO,xO,yO=pcall(kb.modeBonus,tO)
if wO and(xO or 0)>0 then
tO.teamBonus=xO
if not tostring(tO.why):find(Vee[2693],1,true)then
tO.why=(tO.why or Vee[894])..Vee[2347]..yO
end
end
local zO=uO*(tO.value+(tO.teamBonus or 0))/vO
tO.baseScore=zO
local AO,BO,CO=pcall(ib.valueFor,tO)
if AO and BO>0 then
local DO=uO*(tO.value+BO)/(vO*CO)
if DO>zO then
zO,tO.train=DO,BO
end
end
if tO.rec.runs<2 then
zO=zO*(1+O.exploreBonus)
end
return zO
end
