function W.trialTeam()
local GO=P.trial
local HO=GO.list[tonumber(GO.i)or 1]
if P.train.on then
ib.home()
end
local IO=N.session()
local JO,KO
for LO,MO in pairs(IO.profile_data.collection.owned_units)do
if MO.unit_id==HO then
local NO=IO.collection:get_unit_by_uuid(MO.uuid)or MO
local OO,PO=pcall(V.score,NO)
PO=OO and PO or 0
if not KO or PO>KO then
JO,KO=NO,PO
end
end
end
local QO=GO.study and P.study and P.study.id==HO and P.study or nil
if QO and IO.collection:get_unit_by_uuid(QO.uuid)then
JO=IO.collection:get_unit_by_uuid(QO.uuid)
end
if not JO then
F.log(1,Vee[2697],V.name(HO)..Vee[2698])
GO.i=(tonumber(GO.i)or 1)+1
return false
end
local RO=table.clone(P.savedTeam or ib.team())
local SO=table.find(RO,JO.uuid)~=nil
if not SO then
local TO,UO
for VO,WO in ipairs(RO)do
local XO=IO.collection:get_unit_by_uuid(WO)
if XO and not V.isFarm(XO.unit_id)and not V.allyBuff(XO.unit_id)then
local YO,ZO=pcall(V.score,XO)
ZO=YO and ZO or 0
if not UO or ZO<UO then
TO,UO=VO,ZO
end
end
end
if TO then
RO[TO]=JO.uuid
else
table.insert(RO,JO.uuid)
end
end
for _O,aP in ipairs(QO and QO.summoners or{})do
if not table.find(RO,aP)and IO.collection:get_unit_by_uuid(aP)then
local bP,cP
for dP,eP in ipairs(RO)do
local fP=IO.collection:get_unit_by_uuid(eP)
if fP and eP~=JO.uuid and not table.find(QO.summoners,eP)and not V.isFarm(fP.unit_id)and not V.allyBuff(fP.unit_id)then
local gP,hP=pcall(V.score,fP)
hP=gP and hP or 0
if not cP or hP<cP then
bP,cP=dP,hP
end
end
end
if bP then
RO[bP]=aP
elseif#RO<6 then
table.insert(RO,aP)
end
end
end
if not ib.same(ib.team(),RO)then
ab.equipTeam(RO,(QO and Vee[2699]or Vee[2700])..V.name(HO))
end
return true
end
function bb.trialDone(iP,jP)
