if uP.id==lP then
qP=qP+1
rP=math.max(rP,uP.lvl or 0)
sP=sP+(tonumber(pP and pP[0]and pP[0].cost)or 0)
for vP=1,uP.lvl or 0 do
sP=sP+(tonumber(pP and pP[vP]and pP[vP].cost)or 0)
