function db.r3(aQ)
aQ=tonumber(aQ)
return aQ and math.floor(aQ*1000+0.5)/1000 or nil
end
function db.atkBrief(bQ)
if type(bQ)~=Vee[1972]then
return nil
end
local cQ={n=db.r3(bQ.n),hits=bQ.hits}
if(bQ.slow or 0)>0 then
cQ.slow=db.r3(bQ.slowPct)
cQ.slowTime=db.r3(bQ.slowTime)
end
if(bQ.stun or 0)>0 then
cQ.stun=db.r3(bQ.stun)
end
if(bQ.dot or 0)>0 then
cQ.dot=db.r3(bQ.dot)
end
if bQ.bleed then
cQ.bleed=true
end
if(bQ.amp or 0)>0 then
cQ.amp=db.r3(bQ.amp)
end
if bQ.full then
cQ.full=true
end
if bQ.wholeMap then
cQ.wholeMap=true
end
if bQ.breakShields then
cQ.breakShields=true
end
if bQ.ally then
cQ.allyBuff=bQ.ally.types
cQ.allyTime=bQ.ally.time
end
if bQ.allyCd then
cQ.allyCd=bQ.allyCd
end
if bQ.allyRange then
cQ.allyRange=bQ.allyRange
end
if bQ.selfDmg then
cQ.selfDmg=bQ.selfDmg
end
if bQ.baseSafe then
cQ.baseSafe=bQ.baseSafe
end
