local Dxb=Bxb>0 and txb*(Cxb/Bxb-1)or(yxb or 0)
local Exb=uxb[vxb+2]
if Exb and vxb+1<uxb.max and Exb.cd>0 and Axb.cd>0 and Bxb>0 then
local Fxb=txb*((Exb.damage/Exb.cd)/Bxb-1)
local Gxb=wxb+Exb.cost*xxb
if Fxb/Gxb>Dxb/wxb then
Dxb=Dxb+(Fxb/Gxb*wxb-Dxb)*0.5
end
end
local Hxb=(Axb.range or 0)>(zxb.range or 0)and(1+((Axb.range-zxb.range)/math.max(1,zxb.range)))or 1
return math.max(0,Dxb)*Hxb
end
