function bb.buildPath()
bb.samples={}
local Dkc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Dkc then
return
end
for Ekc,Fkc in pairs(Dkc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Ekc.Name])then
local Gkc={}
for Hkc,Ikc in ipairs(Fkc.points or{})do
table.insert(Gkc,Ikc.part.Position)
end
local Jkc=0
for Kkc=2,#Gkc do
Jkc=Jkc+(Gkc[Kkc]-Gkc[Kkc-1]).Magnitude
end
local Lkc=0
for Mkc=2,#Gkc do
local Nkc,Okc=Gkc[Mkc-1],Gkc[Mkc]
local Pkc=(Okc-Nkc).Magnitude
local Qkc=math.max(1,math.floor(Pkc/2))
for Rkc=0,Qkc-1 do
local Skc=Nkc:Lerp(Okc,Rkc/Qkc)
table.insert(bb.samples,{pos=Skc,prog=(Lkc+Pkc*Rkc/Qkc)/math.max(1,Jkc),lane=Ekc.Name})
end
Lkc=Lkc+Pkc
end
if Gkc[#Gkc]then
table.insert(bb.samples,{pos=Gkc[#Gkc],prog=1,lane=Ekc.Name})
end
end
end
pcall(bb.readHidden,Dkc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Tkc=tonumber(bb.ld and bb.ld._portal_lanes)
local Ukc=gb.laneList(bb.samples)
if Tkc and Tkc>=1 and Ukc and#Ukc>Tkc then
bb.laneWant=Tkc
end
bb.laneTotal=Ukc and#Ukc or 1
bb.countLanes()
end
function bb.readHidden(Vkc)
local Wkc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Wkc)~=Vee[1972]or not next(Wkc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Xkc
for Ykc,Zkc in pairs(Vkc)do
if Wkc[Ykc.Name]and type(Zkc.points)==Vee[1972]and#Zkc.points>=2 then
local _kc={}
for alc,blc in ipairs(Zkc.points)do
_kc[alc]=U.flat(blc.part.Position)
end
local clc={}
for dlc,elc in ipairs(bb.samples)do
local flc=tostring(elc.lane)
clc[flc]=clc[flc]or{}
table.insert(clc[flc],elc)
end
local glc,hlc
for ilc,jlc in pairs(clc)do
local klc=0
for llc=1,#_kc,math.max(1,math.floor(#_kc/20))do
local mlc=math.huge
for nlc,olc in ipairs(jlc)do
local plc=(U.flat(olc.pos)-_kc[llc]).Magnitude
if plc<mlc then
mlc=plc
end
end
klc=klc+mlc
end
if not hlc or klc<hlc then
glc,hlc=ilc,klc
end
end
local qlc,rlc,slc,tlc,ulc,vlc={},nil,nil,nil,0,0
for wlc,xlc in ipairs(_kc)do
local ylc,zlc=nil,math.huge
for Alc,Blc in ipairs(clc[glc])do
local Clc=(U.flat(Blc.pos)-xlc).Magnitude
if Clc<zlc then
zlc,ylc=Clc,Blc.prog
end
end
vlc=math.max(vlc,zlc)
if slc then
local Dlc=ylc-slc
local Elc=(Dlc>0.002 and 1)or(Dlc< -0.002 and-1)or tlc
if tlc and Elc and Elc~=tlc then
table.insert(qlc,math.floor(slc*1000+0.5)/1000)
end
tlc,ulc=Elc or tlc,ulc+math.abs(Dlc)
else
rlc=ylc
end
slc=ylc
if wlc%50==0 then
task.wait()
end
end
if slc and vlc<=8 then
table.insert(qlc,math.floor(slc*1000+0.5)/1000)
Xkc=Xkc or{}
Xkc[Ykc.Name]={from=math.floor((rlc or 0)*1000+0.5)/1000,len=math.floor(ulc*1000+0.5)/1000,turns=qlc,road=glc}
end
end
end
if not Xkc then
return
end
local Flc=bb.ld.map
P.maps[Flc]=P.maps[Flc]or{}
local Glc=P.maps[Flc].hidden
P.maps[Flc].hidden=Xkc
if type(Glc)~=Vee[1972]then
for Hlc,Ilc in pairs(Xkc)do
F.log(1,Vee[2634],string.format(Vee[3993],Hlc,Ilc.len,tostring(Ilc.road),math.floor((#Ilc.turns-1)/2)))
end
F.saveSoon()
end
end
