local upc=tpc._stats
if not V.isFarm(upc.id.Value)and upc:FindFirstChild(Vee[2224])then
table.insert(rpc,{p=U.flat(tpc:GetPivot().Position),r=upc.range.Value*(V.SUMMONER[upc.id.Value]and V.SUMMONER[upc.id.Value].reach or 1),air=bb.canAir(tpc)})
