local vpc,wpc=0,0
if#rpc>0 then
for xpc,ypc in ipairs(bb.samples)do
if ypc.prog>wpc then
local zpc=U.flat(ypc.pos)
for Apc,Bpc in ipairs(rpc)do
if(zpc-Bpc.p).Magnitude<=Bpc.r then
if ypc.prog>vpc then
vpc=ypc.prog
end
if Bpc.air then
wpc=ypc.prog
break
end
end
end
end
end
end
local Cpc,Dpc={},bb.laneCount
if Dpc and Dpc.n>=2 and#rpc>0 then
local Epc={}
for Fpc,Gpc in ipairs(bb.samples)do
