for Ipc,Jpc in ipairs(rpc)do
if(Hpc-Jpc.p).Magnitude<=Jpc.r then
local Kpc=tostring(Gpc.lane)
Epc[Kpc]=(Epc[Kpc]or 0)+1
if Gpc.prog>(Cpc[Kpc]or 0)then
Cpc[Kpc]=Gpc.prog
end
break
end
end
end
local Lpc,Mpc={},0
