Mpc=math.max(Mpc,Lpc[Npc])
end
bb.laneW={}
for Ppc,Qpc in pairs(Dpc.by)do
bb.laneW[Ppc]=(Dpc.avg/math.max(1,Qpc))*(1+1.5*(Mpc>0 and(1-Lpc[Ppc]/Mpc)or 0))
