local Wpc=(bb.laneW and Vpc.lane)and(Cpc[tostring(Vpc.lane)]or 0)or vpc
if Vpc.hp>0 and Vpc.prog>Wpc+0.02 and Vpc.prog>(Rpc or 0)then
Rpc,Tpc=Vpc.prog,bb.laneW and Vpc.lane or nil
end
if Vpc.hp>0 and Vpc.fly and Vpc.prog>wpc+0.02 then
Spc=true
end
end
end
local Xpc= #rpc>0 and(bb.pressure or 0)>=vpc-0.08
return{covEnd=vpc,airEnd=wpc,leak=Rpc,leakLane=Tpc,covL=Cpc,airLeak=Spc,push=Xpc,units= #rpc}
end
