local ODc,PDc,QDc,RDc,SDc=0,0,0,0,0
for TDc,UDc in ipairs(KDc)do
local VDc,WDc=UDc.pos.X-NDc.X,UDc.pos.Z-NDc.Z
if VDc*VDc+WDc*WDc<=HDc then
QDc=QDc+1
local XDc=math.min(49,math.floor(UDc.prog*50))
if XDc<25 then
ODc=bit32 .bor(ODc,bit32 .lshift(1,XDc))
else
PDc=bit32 .bor(PDc,bit32 .lshift(1,XDc-25))
end
if UDc.prog-LDc<=0.3 then
RDc=RDc+1
elseif UDc.prog>=0.7 then
SDc=SDc+1
end
end
end
if QDc>0 then
local YDc=ODc..Vee[2107]..PDc
local ZDc=IDc[YDc]
if not ZDc then
ZDc={p=NDc,lo=ODc,hi=PDc,n=QDc,early=RDc,late=SDc}
IDc[YDc]=ZDc
table.insert(JDc,ZDc)
elseif QDc>ZDc.n then
ZDc.p,ZDc.n,ZDc.early,ZDc.late=NDc,QDc,RDc,SDc
end
end
