cEc=true
break
end
end
if not cEc then
table.insert(_Dc,bEc)
end
if aEc%40==0 then
task.wait()
end
end
local fEc,gEc={},{}
local function hEc(iEc)
if iEc and not gEc[iEc]then
gEc[iEc]=true
