local function cFc(dFc)
local eFc,fFc,gFc=0,0,0
for hFc,iFc in ipairs(GEc)do
local jFc=os.clock()
local kFc=gb.runRaw(BEc,CEc,{hpMul=iFc,layout=VEc(dFc),bg=true})
eFc,fFc,gFc=eFc+gb.objective(kFc),fFc+(tonumber(kFc.kills)or 0),gFc+(tonumber(kFc.wave)or 0)
task.wait(math.clamp((os.clock()-jFc)*3,0.25,yEc.pauseMax or 1.5))
if not AEc()then
