function bb.bookSave(iHc,jHc,kHc,lHc)
P.mapBook=type(P.mapBook)==Vee[1972]and P.mapBook or{}
local mHc={}
for nHc,oHc in pairs(kHc.spots or{})do
mHc[nHc]={math.floor(oHc.X*10+0.5)/10,math.floor(oHc.Y*10+0.5)/10,math.floor(oHc.Z*10+0.5)/10}
end
P.mapBook[jHc.key]={spots=mHc,style=jHc.base.style,hp=lHc.hp,n=lHc.n,kills=kHc.kills and math.floor(kHc.kills+0.5)or nil,wave=kHc.wave and math.floor(kHc.wave*10+0.5)/10 or nil,base=lHc.baseWave and math.floor(lHc.baseWave*10+0.5)/10 or nil,label=lHc.label,map=iHc.map,killScore=lHc.kills,at=os.time()}
local pHc={}
for qHc,rHc in pairs(P.mapBook)do
table.insert(pHc,{k=qHc,at=type(rHc)==Vee[1972]and tonumber(rHc.at)or 0})
end
if#pHc>bb.BOOK_MAX then
table.sort(pHc,function(sHc,tHc)
return sHc.at>tHc.at
end)
for uHc=bb.BOOK_MAX+1,#pHc do
P.mapBook[pHc[uHc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(vHc,wHc,xHc)
