return
end
vHc.ended=true
if xHc and wHc then
local yHc=bb.bookFor(wHc.info)
if yHc then
yHc.n=vHc.n
F.saveSoon()
elseif vHc.run>0 then
pcall(bb.bookSave,wHc.info,wHc,xHc,vHc)
end
end
if vHc.run>0 then
F.log(1,Vee[2718],bb.studyWords(vHc))
end
end
