bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
function bb.layoutRecFor(RHc,SHc)
local THc=bb.bookKey(RHc)
P.layoutRec=type(P.layoutRec)==Vee[1972]and P.layoutRec or{}
local UHc=P.layoutRec[THc]
if type(UHc)~=Vee[1972]then
if not SHc then
return nil
end
UHc={at=os.time()}
P.layoutRec[THc]=UHc
if U.count(P.layoutRec)>80 then
local VHc,WHc
for XHc,YHc in pairs(P.layoutRec)do
local ZHc=type(YHc)==Vee[1972]and tonumber(YHc.at)or 0
if not WHc or ZHc<WHc then
VHc,WHc=XHc,ZHc
end
end
P.layoutRec[VHc]=nil
end
end
return UHc
end
function bb.layoutAdd(_Hc,aIc,bIc,cIc,dIc)
_Hc.runs,_Hc.wins=(tonumber(_Hc.runs)or 0)+1,(tonumber(_Hc.wins)or 0)+(aIc and 1 or 0)
_Hc.sec,_Hc.wave=type(_Hc.sec)==Vee[1972]and _Hc.sec or{},type(_Hc.wave)==Vee[1972]and _Hc.wave or{}
if aIc and tonumber(bIc)then
table.insert(_Hc.sec,math.floor(bIc+0.5))
end
table.insert(_Hc.wave,tonumber(cIc)or 0)
if tonumber(dIc)then
_Hc.kills=type(_Hc.kills)==Vee[1972]and _Hc.kills or{}
table.insert(_Hc.kills,math.floor(tonumber(dIc)))
while#_Hc.kills>bb.LAYOUT_KEEP do
table.remove(_Hc.kills,1)
end
end
while#_Hc.sec>bb.LAYOUT_KEEP do
table.remove(_Hc.sec,1)
end
while#_Hc.wave>bb.LAYOUT_KEEP do
table.remove(_Hc.wave,1)
end
end
function bb.layoutJudge(eIc,fIc,gIc,hIc)
local iIc,jIc=tonumber(eIc and eIc.runs)or 0,tonumber(fIc and fIc.runs)or 0
if iIc<1 or jIc<bb.LAYOUT_CONTROL then
return nil
end
if hIc and type(eIc.kills)==Vee[1972]and type(fIc.kills)==Vee[1972]and#eIc.kills>=1 and#fIc.kills>=bb.LAYOUT_CONTROL then
local kIc,lIc=bb.labMedian(eIc.kills),bb.labMedian(fIc.kills)
if kIc and lIc and kIc<lIc*0.97 and(#eIc.kills>=2 or kIc<lIc*0.85)then
return string.format(Vee[4175],kIc,lIc)
end
return nil
end
local mIc,nIc=(tonumber(eIc.wins)or 0)/iIc,(tonumber(fIc.wins)or 0)/jIc
if not gIc and nIc>=0.5 then
if mIc+0.25<nIc and(iIc>=2 or(mIc==0 and nIc>=0.9 and jIc>=3))then
return string.format(Vee[4176],tonumber(eIc.wins)or 0,iIc,iIc==1 and Vee[894]or Vee[1820],tonumber(fIc.wins)or 0,jIc)
end
local oIc,pIc=bb.labMedian(eIc.sec),bb.labMedian(fIc.sec)
if oIc and pIc and oIc>pIc*1.10 and(#eIc.sec>=2 or oIc>pIc*1.25)then
return string.format(Vee[4177],math.floor(oIc/60),oIc%60,math.floor(pIc/60),pIc%60)
end
return nil
end
local qIc,rIc=bb.labMedian(eIc.wave),bb.labMedian(fIc.wave)
if qIc and rIc and qIc<rIc-math.max(1,rIc*0.03)and(iIc>=2 or qIc<rIc*0.85)then
return string.format(Vee[4178],qIc,rIc)
end
return nil
end
function bb.layoutResult(sIc,tIc)
local uIc=bb.info
local vIc=bb.layoutSrc
if not(uIc and vIc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not uIc.timeLimit then
return
end
local wIc=bb.wave()
local xIc=bb.layoutRecFor(uIc,true)
xIc.at=os.time()
local yIc=uIc.timeLimit~=nil
local zIc=uIc.killScore and true or nil
local AIc=zIc and(bb.killsEnd or bb.realKills())or nil
if vIc==Vee[4148]then
local BIc=bb.bookFor(uIc)
if not BIc then
return
end
BIc.real=type(BIc.real)==Vee[1972]and BIc.real or{}
bb.layoutAdd(BIc.real,sIc,tIc,wIc,AIc)
local CIc=BIc.aside==nil and bb.layoutJudge(BIc.real,xIc.own,yIc,zIc)or nil
if CIc then
BIc.aside={at=os.time(),why=CIc}
F.log(1,Vee[4094],string.format(Vee[4179],CIc))
end
else
xIc[vIc]=type(xIc[vIc])==Vee[1972]and xIc[vIc]or{}
local DIc=xIc[vIc]
bb.layoutAdd(DIc,sIc,tIc,wIc,AIc)
if vIc==Vee[3528]and DIc.aside==nil then
local EIc=bb.layoutJudge(DIc,xIc.own,yIc,zIc)
if EIc then
DIc.aside,DIc.why=os.time(),EIc
F.log(1,Vee[4094],string.format(Vee[4180],EIc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Vee[4181],Vee[4182],Vee[4183],Vee[4184]}
function bb.controlSpot(FIc,GIc)
if not bb.killZone()then
return nil
end
local HIc=gb.holds
if not HIc(FIc.id)or V.toggleOf(FIc.id)then
return nil
end
local IIc,JIc,KIc,LIc=1,0,0,{}
local MIc=bb.hurtSamples()
for NIc,OIc in ipairs(bb.mine or{})do
local PIc=OIc._stats
local QIc=PIc.id.Value
if PIc:FindFirstChild(Vee[2224])and not V.isFarm(QIc)and not V.allyBuff(QIc)then
local RIc,SIc=U.flat(OIc:GetPivot().Position),PIc.range.Value
if HIc(QIc)and not V.toggleOf(QIc)then
KIc=KIc+1
table.insert(LIc,{p=RIc,r=SIc})
else
for TIc,UIc in ipairs(MIc)do
if(U.flat(UIc.pos)-RIc).Magnitude<=SIc then
IIc,JIc=math.min(IIc,UIc.prog),math.max(JIc,UIc.prog)
end
end
end
end
end
if JIc<=IIc then
IIc,JIc=0.75,0.98
end
local VIc=(GIc or KIc)+1
local WIc=({IIc,JIc,(IIc+JIc)/2,IIc-(JIc-IIc)/2})[VIc]
if not WIc then
return nil
end
local XIc=V.range(FIc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local YIc={}
for ZIc,_Ic in ipairs(bb.cands)do
local aJc,bJc,cJc=U.flat(_Ic),0,0
for dJc,eJc in ipairs(MIc)do
if(U.flat(eJc.pos)-aJc).Magnitude<=XIc then
cJc=cJc+1
if math.abs(eJc.prog-WIc)<=0.05 then
bJc=bJc+1
local fJc=U.flat(eJc.pos)
for gJc,hJc in ipairs(LIc)do
if(fJc-hJc.p).Magnitude<=hJc.r then
bJc=bJc-0.5
break
end
end
end
end
end
if bJc>0 then
table.insert(YIc,{pos=_Ic,sc=bJc,cov=cJc})
end
if ZIc%60==0 then
task.wait()
end
end
table.sort(YIc,function(iJc,jJc)
return iJc.sc>jJc.sc
end)
for kJc,lJc in ipairs(YIc)do
local mJc=bb.valid(lJc.pos,FIc.data)
if mJc then
F.log(1,Vee[4033],string.format(Vee[4185],V.name(FIc.id),bb.CONTROL_WORDS[VIc],math.floor(WIc*100+0.5)))
return mJc,lJc.cov,WIc
end
if kJc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(nJc)
local oJc,pJc=gb.holds(nJc.id)
if not oJc then
return nil
end
if V.killFed(nJc.id)then
return nil
end
local qJc,rJc={},0
for sJc,tJc in ipairs(bb.mine or{})do
local uJc=tJc._stats
local vJc=uJc.id.Value
if uJc:FindFirstChild(Vee[2224])and not V.isFarm(vJc)and not V.allyBuff(vJc)and vJc~=nJc.id then
local wJc,xJc=pcall(bb.liveDps,tJc,vJc)
xJc=wJc and tonumber(xJc)or 0
if xJc>0 then
table.insert(qJc,{p=U.flat(tJc:GetPivot().Position),r=uJc.range.Value,d=xJc})
rJc=rJc+xJc
end
end
end
if#qJc==0 or rJc<=0 then
return nil
end
local yJc=bb.hurtSamples()
local zJc={}
for AJc,BJc in ipairs(yJc)do
local CJc,DJc=U.flat(BJc.pos),0
for EJc,FJc in ipairs(qJc)do
if(CJc-FJc.p).Magnitude<=FJc.r then
DJc=DJc+FJc.d
end
end
zJc[AJc]=DJc/rJc
end
local GJc=V.range(nJc.u,math.min(tonumber(pJc)or 0,3,V.rows(nJc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local HJc,IJc,JJc
for KJc,LJc in ipairs(bb.cands)do
local MJc,NJc,OJc=U.flat(LJc),0,0
for PJc,QJc in ipairs(yJc)do
if(U.flat(QJc.pos)-MJc).Magnitude<=GJc then
NJc=NJc+zJc[PJc]
OJc=OJc+1
end
end
if NJc>0 and(not IJc or NJc>IJc)then
local RJc=bb.valid(LJc,nJc.data)
if RJc then
HJc,IJc,JJc=RJc,NJc,OJc
end
end
if KJc%40==0 then
task.wait()
end
end
if not HJc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[nJc.id]then
bb.holdSaid[nJc.id]=true
F.log(1,Vee[4033],string.format(Vee[4186],V.name(nJc.id)))
end
return HJc,JJc or 0
end
function bb.bestSpot(SJc,TJc,UJc)
if bb.hybridHill and not SJc._hillTry and type(SJc.data)==Vee[1972]and SJc.data.hybrid_placement and not SJc.data.hill_unit then
local VJc=setmetatable({data=bb.hillData(SJc.data),_hillTry=true},{__index=SJc})
local WJc,XJc,YJc=pcall(bb.bestSpot,VJc,TJc,UJc)
if WJc and XJc then
return XJc,YJc
end
end
if bb.focus and not TJc and not UJc and not V.allyBuff(SJc.id)then
local ZJc,_Jc=bb.focusSpot(SJc)
if ZJc then
return ZJc,_Jc
end
end
if O.fishiFollow and not TJc and not UJc then
local aKc,bKc,cKc,dKc,eKc=pcall(bb.drownBoss)
if aKc and bKc and not cKc and eKc and eKc[SJc.id]then
local fKc,gKc,hKc=pcall(bb.drownSpot,SJc,bKc)
if fKc and gKc then
return gKc,hKc
end
end
end
if not TJc and not UJc and not(bb.depth and bb.depth.leak)then
local iKc,jKc,kKc=pcall(bb.controlSpot,SJc)
if iKc and jKc then
return jKc,kKc
end
local lKc,mKc,nKc=pcall(bb.holdSpot,SJc)
if lKc and mKc then
return mKc,nKc
end
end
local oKc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[SJc.id]and not TJc and not UJc then
local pKc=false
for qKc,rKc in ipairs(bb.mine or{})do
local sKc=rKc._stats:FindFirstChild(Vee[2348])
if sKc and sKc.Value==SJc.uuid then
pKc=true
break
end
end
if not pKc then
for tKc,uKc in ipairs(bb.layout[SJc.id])do
local vKc=bb.valid(uKc,SJc.data)
if vKc and bb.sandLine()>0 and bb.cover(vKc,V.range(SJc.u,V.rows(SJc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
vKc=nil
end
if vKc and oKc then
local wKc,xKc,yKc=false,U.flat(vKc),V.range(SJc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local zKc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for AKc,BKc in ipairs(bb.hurtSamples())do
if BKc.prog>=oKc+0.02 and(not zKc or tostring(BKc.lane)==zKc)and(U.flat(BKc.pos)-xKc).Magnitude<=yKc then
wKc=true
break
end
end
if not wKc then
vKc=nil
end
end
if vKc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[SJc.id]=vKc
return vKc,bb.cover(vKc,V.range(SJc.u,math.min(3,V.rows(SJc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local CKc=SJc.data
local DKc=bb.depth
local EKc,FKc=bb.hurtSamples(),bb.sandLine()
local GKc
if UJc then
GKc=1
for HKc,IKc in ipairs(bb.mine or{})do
local JKc=IKc._stats
if not V.isFarm(JKc.id.Value)and not(JKc:FindFirstChild(Vee[2348])and JKc.uuid.Value==SJc.uuid)then
local KKc,LKc=U.flat(IKc:GetPivot().Position),JKc.range.Value
for MKc,NKc in ipairs(EKc)do
if NKc.prog<GKc and(U.flat(NKc.pos)-KKc).Magnitude<=LKc then
GKc=NKc.prog
end
end
end
end
if V.ENTRY[SJc.id]or(bb.studyEntry and SJc.id==bb.trialId)then
GKc=math.min(GKc,FKc+0.1)
end
end
local OKc=(bb.info and tonumber(bb.info.rangeScale))or 1
local PKc=V.range(SJc.u,(DKc and DKc.leak)and 0 or math.min(3,V.rows(SJc.id).max))*OKc
local QKc=(bb.kind==Vee[1992]or bb.style==Vee[3629]or bb.style==Vee[3630])and not TJc and not(DKc and DKc.leak)and not V.isFarm(SJc.id)and V.range(SJc.u,V.rows(SJc.id).max)*OKc or nil
local RKc=V.allyBuff(SJc.id)
if bb.killZone()and not TJc and not UJc and not RKc and not(DKc and DKc.leak)and not V.isFarm(SJc.id)then
local SKc=QKc or PKc
local TKc={}
for UKc,VKc in ipairs(bb.mine or{})do
local WKc=VKc._stats
local XKc=WKc.id.Value
if not V.isFarm(XKc)and not V.allyBuff(XKc)and WKc:FindFirstChild(Vee[2224])then
table.insert(TKc,{p=U.flat(VKc:GetPivot().Position),r=WKc.range.Value})
end
end
local YKc={}
for ZKc,_Kc in ipairs(EKc)do
local aLc=0
local bLc=U.flat(_Kc.pos)
for cLc,dLc in ipairs(TKc)do
if(bLc-dLc.p).Magnitude<=dLc.r then
aLc=aLc+1
end
end
YKc[ZKc]=aLc
end
local eLc,fLc,gLc
local hLc=0
for iLc,jLc in ipairs(bb.cands)do
local kLc=bb.valid(jLc,CKc)
hLc=hLc+1
if hLc%40==0 then
task.wait()
end
if kLc then
local lLc,mLc,nLc=U.flat(kLc),0,0
for oLc,pLc in ipairs(EKc)do
if(U.flat(pLc.pos)-lLc).Magnitude<=SKc then
nLc=nLc+1
if pLc.prog>=0.6 then
mLc=mLc+(pLc.prog-0.5)*(1+YKc[oLc])
end
end
end
if not fLc or mLc>fLc then
eLc,fLc,gLc=kLc,mLc,nLc
end
end
end
if eLc and fLc>0 then
if not bb.zoneSaid then
bb.zoneSaid=true
F.log(1,Vee[4033],Vee[4187])
end
return eLc,gLc or 0
end
