function bb.buffGain(QRc)
local RRc=V.allyBuff(QRc.id)
if not RRc then
return 0
end
local SRc,TRc,URc=bb.buffShort(RRc)
local VRc=V.stackCap(RRc.attack)
local WRc,XRc=pcall(V.range,QRc.u,0)
XRc=(WRc and tonumber(XRc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local YRc=VRc and O.community and tonumber(RRc.time)and tonumber(URc)
local function ZRc(_Rc,aSc)
local bSc=math.floor(_Rc*RRc.time/math.max(1,URc)+0.001)
return math.min(VRc,(1+aSc)^bSc-1)
end
local cSc=0
for dSc,eSc in ipairs(SRc)do
local fSc=0
for gSc,hSc in ipairs(SRc)do
if(hSc.pos-eSc.pos).Magnitude<=XRc then
local iSc=RRc.types[hSc.base]
local jSc=iSc*RRc.uptime
