function nb.K.key(sNd,tNd)
local uNd,vNd,wNd=nb.K,nb.Win,Enum.KeyCode
if uNd.cur and not(uNd.cur.obj and uNd.cur.obj.Parent and uNd.shown(uNd.cur.obj))then
uNd.setFocus(nil)
end
if uNd.cur and uNd.cur.listKey and uNd.cur.listKey(sNd)then
return true
end
if sNd==wNd.PageUp or sNd==wNd.PageDown then
local xNd={}
for yNd,zNd in pairs(vNd._tabs)do
table.insert(xNd,{name=yNd,y=zNd.btn.AbsolutePosition.Y,on=zNd.page.Visible})
end
table.sort(xNd,function(ANd,BNd)
return ANd.y<BNd.y
end)
local CNd=1
for DNd,ENd in ipairs(xNd)do
if ENd.on then
CNd=DNd
end
end
CNd=(CNd-1+(sNd==wNd.PageDown and 1 or-1))% #xNd+1
uNd.setFocus(nil)
vNd:SelectTab(xNd[CNd].name)
return true
end
if sNd==wNd.Tab or sNd==wNd.Down or sNd==wNd.Up then
local FNd=uNd.order()
if#FNd==0 then
return true
end
local GNd=sNd==wNd.Up or(sNd==wNd.Tab and tNd)
local HNd=table.find(FNd,uNd.cur)
if not HNd then
HNd=GNd and#FNd or 1
else
HNd=(HNd-1+(GNd and-1 or 1))% #FNd+1
end
uNd.setFocus(FNd[HNd])
return true
end
if not uNd.cur then
return false
end
if sNd==wNd.Return or sNd==wNd.KeypadEnter or sNd==wNd.Space then
if uNd.cur.activate then
uNd.cur.activate()
end
return true
end
if sNd==wNd.Left or sNd==wNd.Right then
if uNd.cur.adjust then
uNd.cur.adjust(sNd==wNd.Right and 1 or-1)
end
return true
end
if sNd==wNd.Escape then
uNd.setFocus(nil)
return true
end
return false
end
